INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Pola jahitan tidak berjalan sesuai program', 'Mesin menjalankan pola yang berbeda dari program atau bentuk jahitan tidak sesuai data yang dipilih.', 'Data pola yang dipilih tidak sesuai, program mengalami kesalahan, atau data pola tidak terbaca dengan benar.', 'Periksa nomor pola dan data program yang dipilih. Pastikan file pola sesuai format yang didukung dan data telah dimuat dengan benar.', 'Hentikan mesin sebelum memeriksa atau mengganti program pola.', 'Data spesifikasi JUKI PS-800 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Data pola tidak dapat dimasukkan melalui USB', 'File pola dari USB tidak terbaca atau tidak dapat dimuat ke mesin.', 'Format file tidak sesuai, media USB bermasalah, atau data belum dikonversi sesuai kebutuhan sistem.', 'Periksa media USB dan format data. Pastikan file menggunakan format yang didukung seperti DXF, AI, PLT, atau DST dan telah melalui proses editing/konversi yang sesuai.', 'Matikan atau hentikan proses input sebelum mencabut USB dari mesin.', 'Data spesifikasi program input dan data format JUKI PS-800');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Pola tidak dikenali oleh sistem template', 'Template tidak dikenali atau pola yang terkait dengan template tidak dipilih secara otomatis.', 'RFID atau barcode template tidak terbaca, data template tidak sesuai, atau posisi template tidak tepat.', 'Periksa kondisi RFID/barcode dan posisi template. Pastikan data template terdaftar dan sesuai dengan program pola yang digunakan.', 'Hentikan mesin sebelum memeriksa template atau perangkat pengenalnya.', 'Data spesifikasi template recognition RFID/Barcode JUKI PS-800');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Feed pola tidak bergerak stabil', 'Material atau template bergerak tersendat sehingga hasil pola bergeser dari posisi yang diharapkan.', 'Double stepping motor, belt drive, atau screw drive mengalami gangguan atau gerakan feed terhambat.', 'Periksa area feed dan pastikan tidak ada hambatan mekanis. Periksa gerakan sistem stepping motor dan mekanisme penggerak sesuai konfigurasi mesin.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa mekanisme feed.', 'Data spesifikasi feed mechanism JUKI PS-800 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Intermediate presser tidak mengangkat atau menekan dengan benar', 'Intermediate presser tidak mencapai posisi kerja atau hasil penahanan material tidak stabil.', 'Mekanisme intermediate presser mengalami gangguan atau penyetelan lift tidak sesuai.', 'Periksa mekanisme intermediate presser dan pastikan gerakannya sesuai. Rentang lift yang tersedia sampai 20 mm dengan stroke standar 4 mm.', 'Matikan mesin sebelum memeriksa atau menyetel intermediate presser.', 'Data spesifikasi intermediate presser JUKI PS-800');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Jahitan tidak terbentuk atau benang sering putus', 'Jahitan tidak terbentuk sempurna, benang putus, atau hasil jahitan tidak konsisten.', 'Jarum DB×1 rusak atau tidak sesuai, pemasangan benang kurang tepat, atau kondisi hook tidak normal.', 'Periksa jarum DB×1 dan jalur benang. Periksa area full-rotary double-capacity hook dan pastikan tidak ada kotoran atau gangguan mekanis.', 'Matikan mesin sebelum mengganti jarum atau memeriksa hook.', 'Data spesifikasi needle dan hook JUKI PS-800 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Kapasitas atau penyimpanan pola bermasalah', 'Pola yang disimpan tidak muncul, data pola sulit ditemukan, atau jumlah pola tersimpan tidak sesuai.', 'Data pola tidak tersimpan dengan benar, memori program bermasalah, atau jumlah data mendekati batas kapasitas.', 'Periksa daftar pola yang tersimpan dan kelola data program. Pastikan penyimpanan tidak melampaui kapasitas maksimum 999 pola.', 'Hentikan proses jahit sebelum melakukan pengelolaan atau penghapusan data pola.', 'Data spesifikasi pattern data memory JUKI PS-800');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (11, 'Pelumasan atau gerakan kepala mesin tidak normal', 'Gerakan kepala mesin terasa kasar, suara mekanis meningkat, atau bagian bergerak tidak lancar.', 'Kondisi pelumasan semi-dry/dry head tidak sesuai konfigurasi atau terdapat gangguan pada bagian mekanis.', 'Periksa kondisi sistem pelumasan sesuai konfigurasi PS-800 dan periksa area mekanis dari kotoran atau hambatan.', 'Matikan mesin dan lepaskan sumber listrik sebelum melakukan pemeriksaan atau perawatan.', 'Data spesifikasi lubrication JUKI PS-800 dan panduan pemeriksaan umum');
